from pathlib import Path
import json,re,html
R=Path(__file__).resolve().parents[1];shots=json.loads((R/'redesign/trailer-data.json').read_text());H=lambda s:html.escape(str(s),quote=True)
idx=json.loads((R/'assets/js/search-index.js').read_text().split('=',1)[1].strip().rstrip(';'))
for lang in ['sk','cz']:
 i=1 if lang=='cz' else 0;tr=lambda sk,cs:cs if i else sk;base='/'+lang+'/'
 title=tr('Trailer 1. Záber po zábere.','Trailer 1. Záběr po záběru.')
 desc=tr('Osem vybraných momentov. Čo je viditeľné v zábere a čo je naša interpretácia.','Osm vybraných momentů. Co je viditelné v záběru a co je naše interpretace.')
 timeline='';panels=''
 for n,s in enumerate(shots):
  t=s['second'];time=f'{t//60:02}:{t%60:02}';links=[]
  for target in s['links']:
   d=next(d for d in idx if d['url']==f'{lang}/{target}/');links.append(f'<a href="{base}{target}/">{H(d["title"])} ↗</a>')
  timeline+=f'<a class="shot-link" href="#moment-{t}" data-shot="{t}" {"aria-current=true" if n==0 else ""}><img src="/assets/img/trailer-1/{t:02}-320.webp" width="320" height="180" alt="" loading="lazy"><span><small>{time} / 0{n+1}</small><strong>{H(s["title"][i])}</strong></span><b>↗</b></a>'
  panels+=f'<section id="moment-{t}" class="shot-panel" data-moment="{t}" aria-labelledby="title-{t}"><p class="eyebrow">TRAILER 1 / {time}</p><h2 id="title-{t}">{H(s["title"][i])}</h2><figure><img src="/assets/img/trailer-1/{t:02}.webp" alt="{H(s["observation"][i])}" width="960" height="540" loading="lazy"><figcaption>© ROCKSTAR GAMES / TRAILER 1 / {time}</figcaption></figure><div class="shot-observation"><span>{tr("VIDITEĽNÉ V ZÁBERE","VIDITELNÉ V ZÁBĚRU")}</span><p>{H(s["observation"][i])}</p></div><div class="shot-analysis"><span>{tr("NAŠA INTERPRETÁCIA","NAŠE INTERPRETACE")}</span><p>{H(s["analysis"][i])}</p></div><div class="shot-question"><span>{tr("SKÚS SI VŠIMNÚŤ","ZKUS SI VŠIMNOUT")}</span><p>{H(s["question"][i])}</p></div><a class="button coral play-moment" href="https://www.youtube.com/watch?v=QdBZY2fkU-0&amp;t={t}s" target="_blank" rel="noopener noreferrer" data-seek="{t}">{tr("Prehrať od","Přehrát od")} {time} ▶</a><div class="shot-related"><p class="eyebrow">{tr("SÚVISIACE STOPY","SOUVISEJÍCÍ STOPY")}</p>{''.join(links)}</div></section>'
 main=f'''<nav class="portal-crumbs" aria-label="{tr('Navigácia stránky','Navigace stránky')}"><a href="{base}">{tr('Domov','Domů')}</a><span>/</span><span aria-current="page">Trailery</span></nav><div class="portal-heading"><p class="eyebrow">VICECORE / SCREENING ROOM</p><h1>{title}</h1><p class="portal-deck">{desc}</p></div><div class="trailer-meta"><span>04. 12. 2023 / ROCKSTAR GAMES</span><span>01:30 / 8 {tr('MOMENTOV','MOMENTŮ')}</span><button class="home-save" data-save-id="news:trailer-1-rozbor" aria-pressed="false" aria-label="{tr('Uložiť rozbor traileru','Uložit rozbor traileru')}"><span aria-hidden="true">＋</span><span class="save-label">{tr('Uložiť','Uložit')}</span></button></div>
<section class="screening-player" aria-label="{tr('Oficiálny trailer','Oficiální trailer')}"><div class="video-stage"><video id="trailer-video" controls playsinline preload="none" poster="/assets/img/trailer-1/23.webp" data-src="https://media-rockstargames-com.akamaized.net/VI/downloads/videos/GTAVI_Trailer_1/GTAVI_Trailer_1.mp4" aria-label="Grand Theft Auto VI Trailer 1"></video><div id="video-cover" class="video-cover"><span class="eyebrow">GRAND THEFT AUTO VI / TRAILER 1</span><button id="video-start" class="button coral">{tr('Prehrať trailer','Přehrát trailer')} ▶</button><p>{tr('Video sa načíta z Rockstar CDN až po kliknutí.','Video se načte z Rockstar CDN až po kliknutí.')}</p></div></div><div class="video-source"><a href="https://www.rockstargames.com/VI/trailer-1" target="_blank" rel="noopener noreferrer">{tr('Oficiálny zdroj','Oficiální zdroj')} / ROCKSTAR GAMES ↗</a><a id="youtube-fallback" href="https://www.youtube.com/watch?v=QdBZY2fkU-0" target="_blank" rel="noopener noreferrer">YouTube ↗</a><button id="video-stop" hidden>{tr('Zastaviť a odpojiť video','Zastavit a odpojit video')}</button></div><p id="video-status" class="video-status" aria-live="polite"></p><noscript><p>{tr('Pre interaktívny prehrávač zapni JavaScript alebo otvor oficiálny trailer na YouTube.','Pro interaktivní přehrávač zapni JavaScript nebo otevři oficiální trailer na YouTube.')}</p></noscript></section>
<div class="screening-layout"><nav class="shot-timeline" aria-label="{tr('Vybrané momenty traileru','Vybrané momenty traileru')}"><div class="timeline-heading"><p class="eyebrow">{tr('VYBER SI ZÁBER','VYBER SI ZÁBĚR')}</p><span>8 / TRAILER 1</span></div>{timeline}</nav><div class="shot-panels">{panels}<div class="shot-pagination"><button id="shot-prev" class="button ghost">← {tr('Predošlý záber','Předchozí záběr')}</button><span id="shot-position" aria-live="polite">01 / 08</span><button id="shot-next" class="button ghost">{tr('Ďalší záber','Další záběr')} →</button></div></div></div><div class="portal-notice trailer-notice"><span>↗</span><p>{tr('Toto je rozbor pôvodného Traileru 1, nie najnovší prehľad hry. Pozorovania opisujú konkrétne zábery; komentár je redakčná interpretácia.','Toto je rozbor původního Traileru 1, ne nejnovější přehled hry. Pozorování popisují konkrétní záběry; komentář je redakční interpretace.')}</p><a href="https://www.rockstargames.com/VI/media/videos" target="_blank" rel="noopener noreferrer">{tr('Všetky oficiálne videá','Všechna oficiální videa')} ↗</a></div>'''
 template=(R/lang/'novinky/index.html').read_text();template=re.sub(r'<main id="main".*?</main>',f'<main id="main" class="portal-main shell trailer-page">{main}</main>',template,flags=re.S)
 template=re.sub(r'<title>.*?</title>',f'<title>{title} | ViceCore</title>',template)
 template=re.sub(r'<meta name="description"[^>]+>',f'<meta name="description" content="{desc}">',template)
 template=re.sub(r'<meta property="og:title"[^>]+>',f'<meta property="og:title" content="{title} | ViceCore">',template)
 template=re.sub(r'<meta property="og:description"[^>]+>',f'<meta property="og:description" content="{desc}">',template)
 for attr in ['canonical']:
  template=re.sub(r'<link rel="canonical"[^>]+>',f'<link rel="canonical" href="https://vicecore.matus-sturdik1.workers.dev/{lang}/trailery/">',template)
 template=re.sub(r'(<link rel="alternate" hreflang="(?:sk|cs)" href="https://vicecore.matus-sturdik1.workers.dev/(?:sk|cz)/)novinky/',r'\1trailery/',template)
 # Local language switch stays on the same feature.
 template=re.sub(r'(<div class="languages">.*?</div>)',lambda m:m[0].replace('/novinky/','/trailery/'),template,flags=re.S)
 template=template.replace(f'href="/{lang}/novinky/" aria-current=page',f'href="/{lang}/novinky/"').replace(f'<a href="/{lang}/trailery/" >Trailery</a>',f'<a href="/{lang}/trailery/" aria-current=page>Trailery</a>')
 template=template.replace('</head>','<link rel="stylesheet" href="/assets/css/trailer.css"></head>').replace('</body>','<script defer src="/assets/js/trailer.js"></script></body>')
 folder=R/lang/'trailery';folder.mkdir(exist_ok=True);(folder/'index.html').write_text(template)
print('Generated bilingual shot-by-shot Trailer 1 feature with 8 verified moments.')
